<?php
declare(strict_types=1);
return static function(PDO $p):void {
 foreach(['ledger_accounts'=>['active'=>'TINYINT NOT NULL DEFAULT 1'],'transactions'=>['replaces_id'=>'BIGINT UNSIGNED NULL','edit_reason'=>'VARCHAR(400) NULL']] as $table=>$columns)foreach($columns as $name=>$definition){$q=$p->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?');$q->execute([$table,$name]);if(!$q->fetchColumn())$p->exec('ALTER TABLE '.$table.' ADD COLUMN '.$name.' '.$definition);}
 $q=$p->query("SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='transactions' AND CONSTRAINT_NAME='fk_transaction_replaces'");if(!$q->fetchColumn())$p->exec('ALTER TABLE transactions ADD CONSTRAINT fk_transaction_replaces FOREIGN KEY(household_id,replaces_id) REFERENCES transactions(household_id,id)');
 $p->exec('UPDATE ledger_accounts l JOIN accounts a ON a.ledger_id=l.id AND a.household_id=l.household_id SET l.active=a.active');
 foreach($p->query('SELECT id FROM households')->fetchAll(PDO::FETCH_COLUMN) as $h)foreach(['expense','income'] as $type){$key='uncategorized_'.$type;$q=$p->prepare('SELECT id FROM ledger_accounts WHERE household_id=? AND system_key=?');$q->execute([$h,$key]);$id=$q->fetchColumn();if(!$id){$root=$p->prepare('SELECT id FROM ledger_accounts WHERE household_id=? AND system_key=?');$root->execute([$h,'chart_root_'.$type]);$parent=$root->fetchColumn()?:null;$q=$p->prepare('INSERT INTO ledger_accounts(uuid,household_id,name,class,system_key,parent_id,account_kind) VALUES(?,?,?,?,?,?,?)');$q->execute([\ReadyFinance\Core::uuid(),$h,'Uncategorized '.$type,$type,$key,$parent,$type]);$id=$p->lastInsertId();}$q=$p->prepare('SELECT id FROM categories WHERE household_id=? AND ledger_id=?');$q->execute([$h,$id]);if(!$q->fetchColumn()){$q=$p->prepare('INSERT INTO categories(uuid,household_id,ledger_id,name,type) VALUES(?,?,?,?,?)');$q->execute([\ReadyFinance\Core::uuid(),$h,$id,'Uncategorized '.$type,$type]);}}
 $p->exec("INSERT IGNORE INTO schema_migrations VALUES ('006_editing',UTC_TIMESTAMP(6))");
};
